import {SKILLS,BUILD,SKILL_UNLOCK_LEVELS,skillUnlocked,skillUnlockLevelForBuild} from './engine.js';
import {icon} from './icons.js';
const conditions=[['always','可用即施放'],['low','生命低于60%'],['charge','敌人将重击'],['burn','目标已灼烧']];
export function renderSkills(s){return `<div class="panelPage skillProgressPage">${s.skillAccess?.legacyAll?'<p class="subtleText legacySkillNote">开发旧档保留全部战技；新旅程按等级解锁。</p>':''}<div class="sectionLabel">已装备战技 · 从左至右优先选择可用技能</div><div class="skillLoadout fourSkills">${s.skills.map((k,i)=>{const sk=SKILLS[k];return `<div class="skillSlot ${sk?'':'emptySkill'}"><span class="priorityBadge">0${i+1}${sk?' / CD '+sk.cd:''}</span><button class="skillIconBtn" data-slot="${i}" title="${sk?'更换'+sk.name:'选择技能'}">${sk?icon(k,s.build):'<span>＋</span>'}</button><h3>${sk?sk.name:'空技能槽'}</h3><div class="skillOrder"><button data-skillmove="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="提高优先级">←</button><button data-skillinfo="${k||''}" ${!sk?'disabled':''}>详情</button><button data-skillmove="${i}" data-direction="1" ${i===3?'disabled':''} aria-label="降低优先级">→</button></div><select data-condition="${i}" aria-label="第${i+1}槽触发条件" ${!sk?'disabled':''}>${conditions.map(([v,n])=>`<option value="${v}" ${s.conditions[i]===v?'selected':''}>${n}</option>`).join('')}</select>${sk?`<button class="clearSkill" data-clearskill="${i}">卸下</button>`:''}</div>`}).join('')}</div>${renderBuildPicker(s)}<div class="sectionLabel">矮人战技图鉴 · ${Object.keys(SKILLS).length}项</div><div class="skillPool">${Object.entries(SKILLS).map(([k,v])=>`<button class="skillCatalogEntry ${skillUnlocked(s,k)?'':'skillLocked'}" data-skillinfo="${k}" title="${skillUnlocked(s,k)?'已解锁':'Lv.'+SKILL_UNLOCK_LEVELS[k]+'解锁'}">${icon(k)}<span>${v.name}</span>${skillUnlocked(s,k)?'':`<small class="skillLevelLock">Lv.${SKILL_UNLOCK_LEVELS[k]} 解锁</small>`}</button>`).join('')}</div><p class="subtleText">没有可用技能时自动普攻；增益不叠层，空槽不占行动。</p></div>`;
}
export function renderBuildPicker(s){return `<div class="skillBuildPicker">${BUILD.map(b=>{const ready=b.skills.filter(Boolean).every(k=>skillUnlocked(s,k));return `<button data-build="${b.id}" ${ready?'':'disabled'} title="${ready?'只替换战技配置，不赠送装备':'需要 Lv.'+skillUnlockLevelForBuild(b.id)+' 解锁全部所需战技'}">${icon(b.skills[0],b.id)}<span>${b.name}<small>${ready?'战技预设':'Lv.'+skillUnlockLevelForBuild(b.id)+' 解锁'}</small></span></button>`;}).join('')}<button data-view="loadouts" class="skillPlansLink">${icon('bag')}<span>方案<small>装备与战技</small></span></button></div>`;}
export function renderSkillChoice(s,slot){return `<h2>选择第 ${slot+1} 个战技</h2>${Object.entries(SKILLS).map(([k,v])=>{const unlocked=skillUnlocked(s,k),duplicate=s.skills.some((x,i)=>x===k&&i!==slot);return `<button class="skillChoice ${unlocked?'':'skillLocked'}" data-assign="${k}" data-index="${slot}" ${!unlocked||duplicate?'disabled':''}>${icon(k)}<span><strong>${v.name}</strong><small>${!unlocked?'Lv.'+SKILL_UNLOCK_LEVELS[k]+' 解锁':duplicate?'已在其他战技槽装备':v.desc}</small></span></button>`;}).join('')}`;}
